@layer theme, base, components, utilities;
@layer components.ply-base, components.ply;

@layer components.ply {
  /* Roblox의 action 토큰을 variant에 직접 연결합니다. */
  .rbx-button[data-variant="emphasis"] {
    background-color: var(--rbx-color-action-emphasis-background);
    color: var(--rbx-color-action-emphasis-foreground);
    border-color: var(--rbx-color-action-emphasis-border);
  }
  .rbx-button[data-variant="standard"] {
    background-color: var(--rbx-color-action-standard-background);
    color: var(--rbx-color-action-standard-foreground);
    border-color: var(--rbx-color-action-standard-border);
  }
  .rbx-button[data-variant="soft-emphasis"] {
    background-color: var(--rbx-color-action-soft-emphasis-background);
    color: var(--rbx-color-action-soft-emphasis-foreground);
    border-color: var(--rbx-color-action-soft-emphasis-border);
  }
  .rbx-button[data-variant="sub-emphasis"] {
    background-color: var(--rbx-color-action-sub-emphasis-background);
    color: var(--rbx-color-action-sub-emphasis-foreground);
    border-color: var(--rbx-color-action-sub-emphasis-border);
  }
  .rbx-button[data-variant="subtle"] {
    background-color: var(--rbx-color-action-subtle-background);
    color: var(--rbx-color-action-subtle-foreground);
    border-color: var(--rbx-color-action-subtle-border);
  }
  .rbx-button[data-variant="utility"] {
    background-color: var(--rbx-color-action-utility-background);
    color: var(--rbx-color-action-utility-foreground);
    border-color: var(--rbx-color-action-utility-border);
  }
  .rbx-button[data-variant="over-media"] {
    background-color: var(--rbx-color-action-over-media-background);
    color: var(--rbx-color-action-over-media-foreground);
    border-color: var(--rbx-color-action-over-media-border);
  }
  .rbx-button[data-variant="alert"] {
    background-color: var(--rbx-color-action-alert-background);
    color: var(--rbx-color-action-alert-foreground);
    border-color: var(--rbx-color-action-alert-border);
  }
  .rbx-button[data-variant="link"] {
    background-color: var(--rbx-color-action-link-background);
    color: var(--rbx-color-action-link-foreground);
    border-color: var(--rbx-color-action-link-border);
  }
  /* Foundation Web size map: label line-height is 100%, not body text's 140%. */
  .rbx-button {
    height: auto;
    min-height: 48px;
    padding: 0 12px;
    font: var(--rbx-typography-label-large-font);
    white-space: normal;
    overflow-wrap: anywhere;
    word-break: keep-all;
    min-width: 0;
    max-width: 100%;
    position: relative;
    padding-block: 8px;
  }
  .rbx-button[data-size="md"] {
    height: auto;
    min-height: 40px;
    font: var(--rbx-typography-label-medium-font);
  }
  .rbx-button[data-size="sm"] {
    height: auto;
    min-height: 32px;
    padding: 0 8px;
    gap: 4px;
    padding-block: 4px;
    font: var(--rbx-typography-label-small-font);
  }
  .rbx-button[data-size="xs"] {
    height: auto;
    min-height: 24px;
    padding: 0 8px;
    gap: 4px;
    font: var(--rbx-typography-label-small-font);
    border-radius: 4px;
  }
  .rbx-button[data-variant="utility"] {
    background-color: var(--rbx-color-action-subtle-background);
    color: var(--rbx-color-action-standard-foreground);
  }
  .rbx-button[data-variant="link"] {
    text-decoration: none;
    color: var(--rbx-color-system-emphasis);
  }
  /* 원본은 비활성 강조 버튼을 standard 역할로 바꾼 뒤 opacity 0.5를 적용합니다. */
  .rbx-button:is(:disabled, [data-disabled]):is(
      [data-variant="emphasis"],
      [data-variant="standard"],
      [data-variant="soft-emphasis"],
      [data-variant="alert"]
    ) {
    background-color: var(--rbx-color-action-standard-background);
    color: var(--rbx-color-action-standard-foreground);
  }

  /* 내용의 공간과 읽기 이름은 남기고 로딩 표시만 중앙에 겹칩니다. */
  .rbx-button-label {
    display: inline-flex;
    align-items: center;
    justify-content: inherit;
    gap: inherit;
    min-width: 0;
    overflow-wrap: anywhere;
  }
  .rbx-button[data-loading] > .rbx-button-label {
    opacity: 0;
  }
  .rbx-button-loader {
    position: absolute;
    inset: 0;
    display: grid;
    place-items: center;
    pointer-events: none;
  }

  .rbx-button {
    inline-size: fit-content;
    flex-shrink: 0;
  }
  [data-contrast="enhanced"][data-theme="dark"]
    .rbx-button[data-variant="link"] {
    color: var(--rbx-color-extended-blue-500);
  }
}

"use client";
import { cloneElement, type ComponentProps, type ReactNode } from "react";
import { useRender } from "@base-ui/react/use-render";
import { Button as Primitive } from "@base-ui/react/button";
import { withClassName } from "../../lib/cx";
import { Spinner } from "./spinner";
import "./button.css";

export type ButtonVariant =
  | "emphasis"
  | "standard"
  | "soft-emphasis"
  | "sub-emphasis"
  | "subtle"
  | "utility"
  | "over-media"
  | "alert"
  | "link";
export type ButtonProps = ComponentProps<typeof Primitive> & {
  /** 처리 중 표시를 켜고 재실행을 막습니다. @defaultValue false */
  loading?: boolean;
  /** 버튼의 색상과 강조 수준입니다. @defaultValue "emphasis" */
  variant?: ButtonVariant;
  /** 버튼 높이입니다. @defaultValue "lg" */
  size?: "xs" | "sm" | "md" | "lg";
};
/** variant는 색상 역할, size는 높이를 고릅니다. 원본 Base UI props/ref도 전달합니다. */
export function Button({
  variant = "emphasis",
  size = "lg",
  loading = false,
  disabled,
  children,
  className,
  render,
  focusableWhenDisabled,
  ...props
}: ButtonProps) {
  return (
    <Primitive
      {...props}
      disabled={disabled || loading}
      focusableWhenDisabled={focusableWhenDisabled ?? loading}
      aria-busy={loading || props["aria-busy"]}
      data-loading={loading || undefined}
      data-variant={variant}
      data-size={size}
      className={withClassName("rbx-button", className)}
      render={(elementProps, state) => (
        <ButtonSurface
          elementProps={elementProps}
          state={state}
          render={render}
          loading={loading}
        />
      )}
    >
      {children}
    </Primitive>
  );
}

/** 합성한 링크의 children·ref도 최종 요소에서 보존하며, 로딩 표시가 버튼 폭을 바꾸지 않게 합니다. */
function ButtonSurface({
  elementProps,
  state,
  render,
  loading,
}: {
  elementProps: ComponentProps<"button">;
  state: Primitive.State;
  render: ButtonProps["render"];
  loading: boolean;
}) {
  const { ref, ...props } = elementProps;
  const element = useRender({
    defaultTagName: "button",
    render,
    ref,
    props,
    state: { ...state },
  });
  const children = (element.props as { children?: ReactNode }).children;
  return cloneElement(
    element,
    {},
    <>
      <span className="rbx-button-label">{children}</span>
      {loading && (
        <span className="rbx-button-loader" aria-hidden="true">
          <Spinner size="sm" aria-hidden="true" />
        </span>
      )}
    </>,
  );
}

import type { ComponentProps, CSSProperties, ReactElement } from "react";
import { cx } from "../../lib/cx";
import "./icon.css";
/** ReactChat / Navigation 배포 CSS에서 확인한 glyph. 그림은 CSS mask, 색은 currentColor입니다. */
export type IconName =
  | "icon-regular-house"
  | "icon-regular-person"
  | "icon-regular-speech-bubble-align-center"
  | "icon-regular-two-people"
  | "icon-regular-person-standing"
  | "icon-regular-backpack"
  | "icon-regular-hand-two-arrows-horizontal"
  | "icon-regular-three-people"
  | "icon-regular-fountain-pen-nib"
  | "icon-regular-building-store"
  | "icon-regular-gift-card"
  | "icon-regular-chevron-large-up"
  | "icon-filled-arrow-spin-clockwise"
  | "icon-filled-calendar"
  | "icon-filled-check"
  | "icon-regular-chevron-large-down"
  | "icon-regular-chevron-large-left"
  | "icon-regular-chevron-large-right"
  | "icon-regular-circle-i"
  | "icon-filled-circle-i"
  | "icon-filled-clock"
  | "icon-regular-gear"
  | "icon-filled-globe-simplified"
  | "icon-filled-magnifying-glass"
  | "icon-regular-person-plus"
  | "icon-regular-plus-large"
  | "icon-filled-premium"
  | "icon-regular-roblox-plus"
  | "icon-filled-smartphone-portrait"
  | "icon-filled-speech-bubble-round"
  | "icon-regular-squares-grid-qr"
  | "icon-filled-three-dots-horizontal"
  | "icon-filled-tilt"
  | "icon-regular-triangle-exclamation"
  | "icon-filled-two-people"
  | "icon-filled-verified-backplate"
  | "icon-filled-verified-check"
  | "icon-regular-x";
export type IconProps = Omit<ComponentProps<"span">, "children"> & {
  size?: number;
} & (
    { name: IconName; render?: never } | { name?: never; render: ReactElement }
  );
export function Icon({
  name,
  render,
  size = 20,
  style,
  className,
  ...props
}: IconProps) {
  return (
    <span
      aria-hidden="true"
      {...props}
      data-icon={name}
      data-custom={render ? "" : undefined}
      className={cx("rbx-icon", className)}
      style={{ "--rbx-icon-size": `${size}px`, ...style } as CSSProperties}
    >
      {render}
    </span>
  );
}

@layer theme, base, components, utilities;
@layer components.ply-base, components.ply;
@import "./button.css";
@layer components.ply {
  .rbx-pagination {
    display: flex;
    flex-wrap: nowrap;
    max-width: 100%;
    min-width: 0;
    align-items: center;
    gap: 4px;
  }
  .rbx-pagination > .rbx-button,
  .rbx-pagination-gap {
    min-width: 32px;
    padding-inline: 6px;
    text-align: center;
  }
  .rbx-pagination .rbx-button[aria-current="page"] {
    box-shadow: inset 0 0 0 1px var(--rbx-color-stroke-contrast-alpha);
  }
  .rbx-pagination-gap {
    color: var(--rbx-color-content-default);
  }
  .rbx-pagination:dir(rtl) > .rbx-button .rbx-icon {
    transform: rotate(180deg);
  }

  .rbx-pagination > .rbx-button {
    flex-shrink: 0;
  }
  .rbx-pagination-summary {
    min-width: 0;
    flex: 1;
    text-align: center;
    overflow-wrap: anywhere;
    font: var(--rbx-typography-body-small-font);
    font-variant-numeric: tabular-nums;
  }
  .rbx-pagination-summary {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: center;
    gap: 2px;
  }
  .rbx-pagination-summary input {
    min-width: 2ch;
    max-width: 100%;
    min-height: 32px;
    padding: 2px;
    border: 1px solid var(--rbx-color-stroke-default);
    border-radius: 4px;
    background: transparent;
    color: inherit;
    font: inherit;
    text-align: center;
  }
  .rbx-pagination-summary input:focus-visible {
    outline: 2px solid var(--rbx-focus-ring);
    outline-offset: 1px;
  }
}

"use client";

import {
  useState,
  useEffect,
  useLayoutEffect,
  useRef,
  type ComponentProps,
} from "react";
import { useMergedRef } from "../../lib/use-merged-ref";
import { cx } from "../../lib/cx";
import { paginationItems } from "../../lib/pagination";
import { Button } from "./button";
import { Icon } from "./icon";
import "./pagination.css";

export type PaginationProps = Omit<ComponentProps<"nav">, "children"> & {
  /** 전체 페이지 수입니다. 0이면 페이지 이동 UI를 표시하지 않습니다. */
  pageCount: number;
  /** 현재 페이지입니다. 1부터 시작합니다. */
  page?: number;
  /** 비제어 방식의 시작 페이지입니다. @defaultValue 1 */
  defaultPage?: number;
  onPageChange?: (page: number) => void;
  /** 데이터를 불러오는 동안 이동을 막을 때 사용합니다. @defaultValue false */
  disabled?: boolean;
  /** 페이지 버튼의 접근 가능한 이름입니다. */
  getPageLabel?: (page: number) => string;
};

/** 페이지 선택만 담당합니다. 데이터 요청과 URL 갱신은 onPageChange에서 처리합니다. */
export function Pagination({
  pageCount,
  page,
  defaultPage = 1,
  onPageChange,
  disabled = false,
  getPageLabel = (value) => `${value}페이지`,
  className,
  ref,
  ...props
}: PaginationProps) {
  const [internalPage, setInternalPage] = useState(defaultPage);
  const root = useRef<HTMLElement>(null);
  const mergedRef = useMergedRef(root, ref);
  const [compact, setCompact] = useState(false);
  const restoreFocus = useRef(false);
  const lastCorrection = useRef<string | null>(null);
  const count = Number.isFinite(pageCount)
    ? Math.max(0, Math.min(Number.MAX_SAFE_INTEGER, Math.floor(pageCount)))
    : 0;
  const value = page ?? internalPage;
  const current = Number.isFinite(value)
    ? Math.max(1, Math.min(count, Math.floor(value)))
    : 1;
  const items = paginationItems(current, count);
  // 화면 너비가 아니라 이 탐색 영역에 실제로 주어진 공간을 기준으로 바꿉니다.
  useLayoutEffect(() => {
    const element = root.current;
    if (!element) return;
    const update = () => {
      const button = element.querySelector("button");
      if (!button) return;
      const style = getComputedStyle(button);
      const canvas = element.ownerDocument
        .createElement("canvas")
        .getContext("2d");
      if (canvas) canvas.font = style.font;
      const inset =
        parseFloat(style.paddingLeft) +
        parseFloat(style.paddingRight) +
        parseFloat(style.borderLeftWidth) +
        parseFloat(style.borderRightWidth);
      const gap = parseFloat(getComputedStyle(element).columnGap) || 0;
      const required =
        2 * button.getBoundingClientRect().width +
        gap * (items.length + 1) +
        items.reduce<number>(
          (sum, item) =>
            sum +
            Math.max(
              32,
              (canvas?.measureText(
                String(typeof item === "number" ? item : "…"),
              ).width ?? 16) + inset,
            ),
          0,
        );
      const next = element.clientWidth < required;
      const focused = element.ownerDocument.activeElement;
      const willRemoveFocus = next
        ? focused?.hasAttribute("data-page-number")
        : focused?.matches(".rbx-pagination-summary input");
      if (
        next !== element.hasAttribute("data-compact") &&
        willRemoveFocus &&
        element.contains(focused)
      )
        restoreFocus.current = true;
      setCompact(next);
    };
    update();
    const observer = new ResizeObserver(update);
    observer.observe(element);
    element.ownerDocument.fonts.addEventListener("loadingdone", update);
    return () => {
      observer.disconnect();
      element.ownerDocument.fonts.removeEventListener("loadingdone", update);
    };
  }, [current, count]);
  useLayoutEffect(() => {
    if (!restoreFocus.current) return;
    restoreFocus.current = false;
    root.current?.querySelector<HTMLElement>('[aria-current="page"]')?.focus();
  }, [compact]);
  // 필터 변경으로 범위를 벗어나면 UI와 내부 상태·호출자의 데이터가 같은 페이지를 가리키게 합니다.
  useEffect(() => {
    if (!count || value === current) {
      lastCorrection.current = null;
      return;
    }
    const correction = String(value) + ":" + current;
    if (lastCorrection.current === correction) return;
    lastCorrection.current = correction;
    if (page === undefined) setInternalPage(current);
    onPageChange?.(current);
  }, [count, value, current, page, onPageChange]);
  function select(next: number) {
    if (disabled || next === current || next < 1 || next > count) return;
    if (page === undefined) setInternalPage(next);
    onPageChange?.(next);
  }
  if (count === 0) return null;
  return (
    <nav
      aria-label="페이지 이동"
      ref={mergedRef}
      data-compact={compact || undefined}
      {...props}
      className={cx("rbx-pagination", className)}
    >
      <Button
        size="sm"
        variant="utility"
        aria-label="이전 페이지"
        disabled={disabled || current === 1}
        onClick={() => select(current - 1)}
      >
        <Icon name="icon-regular-chevron-large-left" size={16} />
      </Button>
      {!compact &&
        items.map((item) =>
          typeof item === "number" ? (
            <Button
              key={item}
              data-page-number={item}
              size="sm"
              variant={item === current ? "standard" : "utility"}
              aria-label={getPageLabel(item)}
              aria-current={item === current ? "page" : undefined}
              disabled={disabled}
              onClick={() => select(item)}
            >
              {item}
            </Button>
          ) : (
            <span key={item} className="rbx-pagination-gap" aria-hidden="true">
              …
            </span>
          ),
        )}
      {compact && (
        <PageInput
          page={current}
          count={count}
          disabled={disabled}
          onCommit={select}
        />
      )}
      <Button
        size="sm"
        variant="utility"
        aria-label="다음 페이지"
        disabled={disabled || current === count}
        onClick={() => select(current + 1)}
      >
        <Icon name="icon-regular-chevron-large-right" size={16} />
      </Button>
    </nav>
  );
}

/** 좁은 화면에서도 여러 페이지를 한 번에 이동할 수 있게 직접 입력을 유지합니다. */
function PageInput({
  page,
  count,
  disabled,
  onCommit,
}: {
  page: number;
  count: number;
  disabled: boolean;
  onCommit: (page: number) => void;
}) {
  const [draft, setDraft] = useState(String(page));
  useEffect(() => {
    setDraft(String(page));
  }, [page, count]);
  const commit = () => {
    const number = Number(draft);
    if (draft.trim() && Number.isFinite(number))
      onCommit(Math.max(1, Math.min(count, Math.floor(number))));
    setDraft(String(page));
  };
  return (
    <span className="rbx-pagination-summary">
      <input
        aria-label="이동할 페이지"
        aria-current="page"
        inputMode="numeric"
        value={draft}
        disabled={disabled}
        style={{ width: Math.min(String(count).length + 1, 8) + "ch" }}
        onChange={(event) => setDraft(event.target.value)}
        onBlur={commit}
        onKeyDown={(event) => {
          if (event.key === "Enter") {
            event.preventDefault();
            commit();
          } else if (event.key === "Escape") {
            setDraft(String(page));
            event.stopPropagation();
          }
        }}
      />
      <span> / {count}</span>
    </span>
  );
}

@layer theme, base, components, utilities;
@layer components.ply-base, components.ply;

@layer components.ply {
  .rbx-spinner {
    display: inline-block;
    flex-shrink: 0;
    width: 20px;
    height: 20px;
    border: 2px solid currentColor;
    border-inline-end-color: transparent;
    border-radius: 50%;
    vertical-align: middle;
    animation: rbx-spinner-rotate 800ms linear infinite;
  }
  .rbx-spinner[data-size="sm"] {
    width: 16px;
    height: 16px;
  }
  .rbx-spinner[data-size="lg"] {
    width: 28px;
    height: 28px;
    border-width: 3px;
  }
  @keyframes rbx-spinner-rotate {
    to {
      transform: rotate(360deg);
    }
  }
  @media (prefers-reduced-motion: reduce) {
    .rbx-spinner {
      animation: none;
    }
  }
}

import type { ComponentProps } from "react";
import { cx } from "../../lib/cx";
import "./spinner.css";

export type SpinnerProps = Omit<ComponentProps<"span">, "children"> & {
  /** 표시 크기입니다. @defaultValue "md" */
  size?: "sm" | "md" | "lg";
  /** 스크린 리더가 읽을 진행 상태입니다. @defaultValue "처리 중" */
  label?: string;
};

/** 진행률을 모르는 짧은 작업에 사용합니다. 진행률이 있으면 Progress를 사용합니다. */
export function Spinner({
  size = "md",
  label = "처리 중",
  className,
  ...props
}: SpinnerProps) {
  return (
    <span
      role="status"
      aria-label={label}
      {...props}
      data-size={size}
      className={cx("rbx-spinner", className)}
    />
  );
}

/** Base UI는 className에 문자열 또는 상태 함수를 받습니다. 둘 다 보존합니다. */
export function withClassName<State>(
  base: string,
  custom?: string | ((state: State) => string | undefined),
) {
  return (state: State) =>
    [base, typeof custom === "function" ? custom(state) : custom]
      .filter(Boolean)
      .join(" ");
}
export function cx(...classes: (string | undefined | false)[]) {
  return classes.filter(Boolean).join(" ");
}

/** 목록 길이와 무관하게 처음·끝·현재 주변 페이지만 만듭니다. */
export function paginationItems(
  page: number,
  count: number,
): Array<number | "gap-start" | "gap-end"> {
  const pages = new Set([1, count, page - 1, page, page + 1]);
  if (page <= 3) for (let n = 1; n <= 5; n++) pages.add(n);
  if (page >= count - 2) for (let n = count - 4; n <= count; n++) pages.add(n);
  const visible = [...pages]
    .filter((n) => n >= 1 && n <= count)
    .sort((a, b) => a - b);
  const result: Array<number | "gap-start" | "gap-end"> = [];
  for (const [index, value] of visible.entries()) {
    const previous = visible[index - 1];
    if (previous !== undefined && value - previous === 2)
      result.push(previous + 1);
    else if (previous !== undefined && value - previous > 2)
      result.push(value <= page ? "gap-start" : "gap-end");
    result.push(value);
  }
  return result;
}

"use client";
import { useCallback, type Ref, type RefObject } from "react";
/** 내부 측정 ref와 호출자의 ref를 함께 연결하고 React 19의 ref 정리 함수도 보존합니다. */
export function useMergedRef<T>(local: RefObject<T | null>, external?: Ref<T>) {
  return useCallback(
    (node: T | null) => {
      local.current = node;
      const cleanup =
        typeof external === "function" ? external(node) : undefined;
      if (external && typeof external !== "function") external.current = node;
      return () => {
        local.current = null;
        if (typeof cleanup === "function") cleanup();
        else if (typeof external === "function") external(null);
        else if (external) external.current = null;
      };
    },
    [local, external],
  );
}

